Definition own (E : Z) (R : bvmap 5 word) (M : mem) : Prop :=
  L5.u64_at RSEGS M (E - 8) (bvu (getr R (reg 1))) /\ L5.u64_at RSEGS M (E - 16) (bvu (getr R (reg 8))) /\ L5.u64_at RSEGS M (E - 24) (bvu (getr R (reg 9))) /\ L5.u64_at RSEGS M (E - 32) (bvu (getr R (reg 18)))
  /\ L5.u64_at RSEGS M (E - 40) (bvu (getr R (reg 19))) /\ L5.u64_at RSEGS M (E - 48) (bvu (getr R (reg 20))) /\ L5.u64_at RSEGS M (E - 56) (bvu (getr R (reg 21))) /\ L5.u64_at RSEGS M (E - 64) (bvu (getr R (reg 22))) /\ L5.u64_at RSEGS M (E - 72) (bvu (getr R (reg 23)))
  /\ L5.u64_at RSEGS M (E - 80) (bvu (getr R (reg 24))) /\ L5.u64_at RSEGS M (E - 88) (bvu (getr R (reg 25))) /\ L5.u64_at RSEGS M (E - 96) (bvu (getr R (reg 26))) /\ L5.u64_at RSEGS M (E - 104) (bvu (getr R (reg 27))).
Definition ocell (E : Z) (a : Z) : Prop := E - 104 <= a < E.
Lemma own_agree E R M1 M1' : 0 <= E - 104 -> E <= 2 ^ 64 ->
  own E R M1 -> (forall a, ocell E a -> M1' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> own E R M1'.
Proof.
