        /\ getr R' (reg 1) = Z_to_bv 64 868220
        /\ getr R' (reg 10) = Z_to_bv 64 (V 45%nat)
        /\ getr R' (reg 11) = edenot (Env (fun j : nat => match j with 2%nat => Z_to_bv 64 (V 2%nat) | 34%nat => Z_to_bv 64 (V 34%nat) | 35%nat => Z_to_bv 64 (V 35%nat) | 45%nat => Z_to_bv 64 (V 45%nat) | _ => getr R (reg j) end) (fun _ => [])) (EAlu Instr.ALU_AND (EAlu Instr.ALU_ADD (EAlu Instr.ALU_AND (EAluw Instr.ALU_SUB (EVar 34) (EMd Instr.M_MUL (ELit 10) (EAlu Instr.ALU_SRL (EMd Instr.M_MULHU (EVar 34) (ELit 14757395258967641293)) (ELit 3)))) (ELit (-49))) (ELit 48)) (ELit 255))
        /\ getr R' (reg 19) = Z_to_bv 64 (V 35%nat)
