  apply L5K.nth_error_single in Hnth. subst ps.
  change (SR.ps_pc PqtwG.ps0) with 0xf4640 in Hms. change (SR.ps_regs PqtwG.ps0) with (map (fun i => (i, nth i PqtwG.regs_out0 (ELit 0))) (seq 1 31)) in Hregs.
