  split. { rewrite (BG.out_reg PqtwG.regs_out0 E' R' 10 Hregs) by (clear; lia). cbn [nth PqtwG.regs_out0]. first [reflexivity | wordP' ZA Hag]. }
  split. { rewrite (BG.out_reg PqtwG.regs_out0 E' R' 11 Hregs) by (clear; lia). cbn [nth PqtwG.regs_out0]. rewrite (BG.edenot_kept 80 E E' _ Hag) by (vm_compute; reflexivity). subst E; reflexivity. }
  split. { rewrite (BG.out_reg PqtwG.regs_out0 E' R' 19 Hregs) by (clear; lia). cbn [nth PqtwG.regs_out0]. first [reflexivity | wordP' ZA Hag]. }
  rewrite (BG.out_reg PqtwG.regs_out0 E' R' 24 Hregs) by (clear; lia). cbn [nth PqtwG.regs_out0]. (L5K.evalB' ZA Hag; pvz_unfold ZA). den_tac. 
