(* [comment removed for export] *)
Definition RIL (R' : bvmap 5 word) (q flag : Z) : Prop :=
  getr R' (reg 2) = Z_to_bv 64 (sp - 112) /\ getr R' (reg 8) = Z_to_bv 64 so /\ getr R' (reg 9) = Z_to_bv 64 dp /\
  getr R' (reg 18) = Z_to_bv 64 q /\ getr R' (reg 19) = Z_to_bv 64 q /\ getr R' (reg 20) = Z_to_bv 64 (so / 8 + 2147450880) /\
  getr R' (reg 21) = Z_to_bv 64 (buf + n) /\ getr R' (reg 22) = Z_to_bv 64 flag /\ getr R' (reg 23) = Z_to_bv 64 10 /\
  getr R' (reg 24) = Z_to_bv 64 68 /\ getr R' (reg 25) = Z_to_bv 64 2147450880 /\ getr R' (reg 26) = Z_to_bv 64 43 /\ getr R' (reg 27) = Z_to_bv 64 101 /\
  (forall j, In j [3; 4]%nat -> getr R' (reg j) = getr R (reg j)).
Lemma RIL_call R1 R2 q flag : RIL R1 q flag -> regs_preserved R1 R2 -> RIL R2 q flag.
