Lemma RIL_leaf R1 R2 (ks : list nat) q flag q' flag' :
  RIL R1 q flag -> (forall j, In j ks -> getr R2 (reg j) = getr R1 (reg j)) ->
  inks [2; 8; 9; 20; 21; 23; 24; 25; 26; 27; 3; 4]%nat ks = true ->
  getr R2 (reg 18) = Z_to_bv 64 q' -> getr R2 (reg 19) = Z_to_bv 64 q' -> getr R2 (reg 22) = Z_to_bv 64 flag' -> RIL R2 q' flag'.
